function card(p,external=false){const metric=p.rank?`${esc(p.metricType||'Rank')} ${esc(p.rank)} · ${esc(p.metricYear||'')}`:'Venue metrics not recorded';return `<article class="paper-card"><div class="card-top"><span class="badge ${p.status}"><i></i>${external?'DISCOVERED':p.status==='read'?'Read':p.status==='reading'?'Reading':'Unread'}</span>${external?`<button class="star-button" data-import="${esc(p.id)}" title="Add to library" aria-label="Add ${esc(p.title)} to library">+</button>`:`<button class="star-button ${p.importance==='high'?'on':''}" data-star="${esc(p.id)}" aria-label="${p.importance==='high'?'Remove importance from':'Mark important:'} ${esc(p.title)}">${p.importance==='high'?'★':'☆'}</button>`}</div><button class="paper-title" ${external?'data-external':'data-paper'}="${esc(p.id)}">${esc(p.title)}</button><div class="authors">${esc(p.authors||'Authors not recorded')}</div><div class="tags">${(p.tags||[]).slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-bottom"><span class="venue" title="${esc(p.venue)}">${icon('venue')}${esc(p.venue||'Venue not recorded')}</span><span class="paper-year">${icon('link')}${esc(p.year||'—')}</span></div><div class="metric-line">${metric}</div></article>`}
