function render(){if(remoteMode&&!confirmed){showLogin();return}updateSidebar();$('#breadcrumb').textContent=collection||labels[view];if(view==='settings'){renderSettings();return}if(view==='discover'){renderDiscover();return}if(isPhone()){renderPhoneLibrary();return}const unread=papers.filter(p=>p.status==='unread').length;const title=collection||labels[view];$('#main').innerHTML=heading(title,view==='queue'?'Turn your reading list into your next great idea.':view==='favorites'?'The papers you want to keep close.':'A home for the ideas that move your research forward.')+`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('spark')} A LITTLE DIRECTION FOR YOUR NEXT READ</div><h2>${view==='queue'?'Good research starts with one paper.':'Your next idea is waiting in your library.'}</h2><p>${unread?`You have ${unread} unread papers. Let’s find a good place to start.`:'Your reading queue is clear. Discover something new to explore.'}</p><button class="button" id="pick-paper">${icon('book')}${unread?'Pick my next read':'Discover papers'} ${icon('arrow')}</button>${view==='queue'?'<div class="queue-options"><label><input id="prefer-important" type="checkbox" checked> Prefer important papers</label><label><input id="random-pick" type="checkbox"> Surprise me</label></div>':''}</div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="art-ring second"></div><div class="book-cover"></div><div class="book-front"><small>COLLECTED IDEAS</small><em>A world<br>of possibility.</em><div class="lines"></div></div><span class="spark">✦</span></div></section><div class="stats">${[[papers.length,'Total papers','library'],[unread,'Waiting to be read','clock'],[papers.filter(p=>p.status==='read').length,'Papers read','check'],[papers.filter(p=>p.importance==='high').length,'Important papers','star']].map(([n,l,i])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><strong>${n}</strong><small>${l}</small></div></div>`).join('')}</div><div class="section-title"><h2>${collection|| (view==='queue'?'Your unread papers':view==='favorites'?'Your important papers':'Your library')}<span id="result-count"></span></h2><span class="subtle-link">Small steps. New perspectives.</span></div>${desktopTagFilters()}<div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Search by title, author, or keyword…" aria-label="Search papers" value="${esc(query)}"></label><select id="status-filter" aria-label="Filter reading status"><option value="all">All statuses</option><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select><select id="priority-filter" aria-label="Filter importance"><option value="all">All importance</option><option value="high">High importance</option><option value="normal">Normal importance</option><option value="low">Low importance</option></select><select id="sort" aria-label="Sort papers"><option value="newest">Newest added</option><option value="oldest">Oldest added</option><option value="year">Publication year</option><option value="title">Title A–Z</option><option value="importance">Importance</option></select><div class="view-toggle"><button data-layout="grid" class="${layout==='grid'?'selected':''}" aria-label="Grid view">${icon('grid')}</button><button data-layout="list" class="${layout==='list'?'selected':''}" aria-label="List view">${icon('list')}</button></div></div><div class="paper-grid ${layout==='list'?'list':''}" id="paper-results"></div>${papers.some(p=>p.sample)?'<div class="sample-note"><span>Explore with a sample library. Your own papers belong here, too.</span><button id="remove-samples">Remove sample papers</button></div>':''}`;renderPapers();$('#status-filter').value=statusFilter;$('#priority-filter').value=priorityFilter;$('#sort').value=sort;$('#search').oninput=e=>{query=e.target.value;renderPapers()};['status','priority'].forEach(type=>$('#'+type+'-filter').onchange=e=>{if(type==='status')statusFilter=e.target.value;else priorityFilter=e.target.value;renderPapers()});$('#sort').onchange=e=>{sort=e.target.value;renderPapers()};}
function modal(html){$('#modal-content').innerHTML=`<div class="modal-inner">${html}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}
function modalTitle(title){return `<div class="modal-header"><h2>${esc(title)}</h2><button class="close" data-close aria-label="Close dialog">×</button></div>`}
function existingTags(){const tags=new Map();for(const tag of [...(settings.collections||[]),...papers.flatMap(p=>p.tags||[])]){const value=tag.trim();if(value&&!tags.has(value.toLowerCase()))tags.set(value.toLowerCase(),value)}return [...tags.values()].sort((a,b)=>a.localeCompare(b))}
function parseTags(value){const known=new Map(existingTags().map(t=>[t.toLowerCase(),t]));const result=new Map();for(const part of value.split(',')){const tag=part.trim();if(tag&&!result.has(tag.toLowerCase()))result.set(tag.toLowerCase(),known.get(tag.toLowerCase())||tag)}return [...result.values()]}
function collectionSettings(){return `<section class="panel"><h2>Collections & tags</h2><p>Rename collections across your library or remove tags from papers.</p><button type="button" class="button" data-manage-collections>Manage collections</button></section>`}
async function changeCollection(oldName,newName){
 if(saving)throw new Error('Please wait for the current save or upload.');
 const same=t=>t.toLowerCase()===oldName.toLowerCase();
 if(!existingTags().some(same))throw new Error('This collection no longer exists.');
 let target=null;
 if(newName!==null){target=newName.trim();if(!target||target.length>200||target.includes(','))throw new Error('Enter a collection name of 1–200 characters without commas.');target=existingTags().find(t=>!same(t)&&t.toLowerCase()===target.toLowerCase())||target}
 const beforePapers=papers,beforeSettings=settings;
 const unique=tags=>[...new Map(tags.map(t=>[t.toLowerCase(),t])).values()];
 papers=papers.map(p=>{if(!(p.tags||[]).some(same))return p;return {...p,tags:unique(p.tags.flatMap(t=>same(t)?target===null?[]:[target]:[t])),updated:Date.now()}});
 settings={...settings,collections:unique((settings.collections||[]).flatMap(t=>same(t)?target===null?[]:[target]:[t]))};
 if(target&&!settings.collections.some(t=>t.toLowerCase()===target.toLowerCase()))settings.collections.push(target);
 try{if(remoteMode)await persistRemote();else{await save();await saveSettings()}}
 catch(err){if(!remoteMode){papers=beforePapers;settings=beforeSettings}throw err}
 if(collection&&same(collection)){collection=target||'';location.hash=collection?'collection='+encodeURIComponent(collection):view}
 return target;
}
function manageCollections(){
 const tags=existingTags();
 modal(modalTitle('Manage collections.')+`<p class="collection-help">Rename a tag everywhere it is used. Removing a tag keeps your paper records.</p><div id="collection-manager" class="collection-manager">${tags.length?tags.map(tag=>`<div class="collection-manager-row"><div><strong>${esc(tag)}</strong><small>${papers.filter(p=>(p.tags||[]).some(t=>t.toLowerCase()===tag.toLowerCase())).length} papers</small></div><div class="collection-row-actions"><button type="button" class="button" data-rename-tag="${esc(tag)}" aria-label="Rename ${esc(tag)}">Rename</button><button type="button" class="button danger" data-remove-tag="${esc(tag)}" aria-label="Remove ${esc(tag)}">Remove</button></div></div>`).join(''):'<p>No collections yet. Create one or add tags to a paper.</p>'}</div><div class="modal-actions"><button type="button" class="button" data-close>Done</button><button type="button" class="button primary" id="add-collection">${icon('plus')}New collection</button></div>`);
 $('#collection-manager').onclick=e=>{if(saving)return;const b=e.target.closest('button');if(!b)return;if(b.dataset.renameTag)renameCollection(b.dataset.renameTag);if(b.dataset.removeTag){const tag=b.dataset.removeTag;const count=papers.filter(p=>(p.tags||[]).some(t=>t.toLowerCase()===tag.toLowerCase())).length;confirmAction('Remove '+tag+'?',`Remove this tag from ${count} ${count===1?'paper':'papers'} and from your collections? Your papers and notes are kept.`,async()=>{await changeCollection(tag,null);toast('Collection removed.')})}};
}
function renameCollection(tag){
 modal(modalTitle('Rename collection.')+`<form id="rename-collection-form"><div class="field"><label for="rename-collection-name">Collection name</label><input id="rename-collection-name" value="${esc(tag)}" required maxlength="200"><small>Updates every paper using this tag. Choosing an existing collection name merges the two collections.</small></div><div id="rename-collection-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" id="back-to-collections">Back</button><button type="submit" class="button primary" id="save-collection-name">Save name</button></div></form>`);
 $('#back-to-collections').onclick=manageCollections;
 $('#rename-collection-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const button=$('#save-collection-name');button.disabled=true;try{await changeCollection(tag,$('#rename-collection-name').value);render();manageCollections();toast('Collection updated.')}catch(err){$('#rename-collection-error').textContent=err.message}finally{button.disabled=false}};
}
function tagField(id,value=''){return `<div class="field tag-field"><label for="${id}">Collections / tags</label><input id="${id}" value="${esc(value)}" placeholder="Type to find a collection…" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}-suggestions" aria-describedby="${id}-help"><div id="${id}-suggestions" class="tag-suggestions" role="listbox" aria-label="Existing collections" hidden></div><small id="${id}-help">Choose an existing tag, or type a new one. Separate multiple tags with commas.</small></div>`}
function attachTagSuggestions(id){
 const input=$('#'+id),list=$('#'+id+'-suggestions');let matches=[],active=-1,dismissed=false;
 const token=()=>{const caret=input.selectionStart??input.value.length;const start=caret===0?0:input.value.lastIndexOf(',',caret-1)+1;const next=input.value.indexOf(',',caret);return {start,end:next<0?input.value.length:next}};
 const hide=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant')};
 const paint=()=>{list.innerHTML=matches.map((tag,i)=>`<button type="button" role="option" tabindex="-1" id="${id}-option-${i}" data-tag-index="${i}" aria-selected="${i===active}" class="${i===active?'active':''}">${esc(tag)}</button>`).join('');list.hidden=!matches.length;input.setAttribute('aria-expanded',String(!!matches.length));if(active>=0)input.setAttribute('aria-activedescendant',id+'-option-'+active);else input.removeAttribute('aria-activedescendant')};
 const update=()=>{if(dismissed)return;const {start,end}=token();const query=input.value.slice(start,end).trim().toLowerCase();const selected=new Set(parseTags(input.value.slice(0,start)+input.value.slice(end)).map(t=>t.toLowerCase()));matches=existingTags().filter(t=>!selected.has(t.toLowerCase())&&t.toLowerCase().includes(query)).sort((a,b)=>Number(b.toLowerCase().startsWith(query))-Number(a.toLowerCase().startsWith(query))||a.localeCompare(b));active=-1;paint()};
 const choose=index=>{const tag=matches[index];if(!tag)return;const {start,end}=token();const prefix=input.value.slice(0,start);const suffix=input.value.slice(end);const replacement=(prefix?' ':'')+tag+(suffix?'':', ');input.value=prefix+replacement+suffix;input.focus();input.setSelectionRange(prefix.length+replacement.length,prefix.length+replacement.length);hide();dismissed=true};
 input.oninput=()=>{dismissed=false;update()};input.onfocus=()=>{dismissed=false;update()};input.onclick=()=>{dismissed=false;update()};input.onblur=hide;
 input.onkeydown=e=>{if(e.isComposing)return;if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();dismissed=true;hide();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden){dismissed=false;update()}if(matches.length){active=(active+(e.key==='ArrowDown'?1:active<0?0:-1)+matches.length)%matches.length;paint();$('#'+id+'-option-'+active)?.scrollIntoView({block:'nearest'})}}else if(e.key==='Enter'&&!list.hidden&&matches.length){e.preventDefault();choose(active<0?0:active)}};
 list.onmousedown=e=>e.preventDefault();list.onclick=e=>{const button=e.target.closest('[data-tag-index]');if(button)choose(Number(button.dataset.tagIndex))};
}
let addMode='url',lookedUpMetadata=null,metadataLookupSequence=0;
function addPaper(){addMode='url';renderAdd()}
function renderAdd(){lookedUpMetadata=null;metadataLookupSequence++;modal(modalTitle('Make room for a new idea.')+`<p style="font-size:12px">Add a paper from a link or enter your own citation details.</p><div class="tabs"><button data-add-tab="url" class="${addMode==='url'?'active':''}">Paper URL / DOI</button><button data-add-tab="manual" class="${addMode==='manual'?'active':''}">Manual entry</button></div><form id="add-form">${addMode==='url'?'<div class="field"><label for="paper-url">Paper URL or DOI</label><input id="paper-url" placeholder="https://eprint.iacr.org/2019/953 or 10.1137/0218012"><small>IACR ePrint, arXiv, publisher links, or a DOI. IACR ePrint, IEEE Xplore, ACM Digital Library, Springer chapters, TCHES articles, and DOIs can fill citation details. Paste a link, then click Look up metadata.</small></div><button type="button" class="button" id="lookup">'+icon('search')+'Look up metadata</button>':'<div class="field"><label for="paper-url">Paper URL or DOI</label><input id="paper-url" placeholder="Optional paper link or DOI"></div>'}<div class="field"><label for="paper-title">Title *</label><input id="paper-title" required maxlength="500" placeholder="The title of the paper"></div><div class="field"><label for="paper-authors">Authors</label><input id="paper-authors" placeholder="Separate authors with semicolons"></div><div class="two-fields"><div class="field"><label for="paper-year">Publication year</label><input id="paper-year" type="number" min="1400" max="2100" placeholder="2026"></div><div class="field"><label for="paper-venue">Conference / journal</label><input id="paper-venue" placeholder="e.g. EUROCRYPT"></div></div>${tagField('paper-tags')}<div class="two-fields"><div class="field"><label for="paper-status">Reading status</label><select id="paper-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div><div class="field"><label for="paper-priority">Importance</label><select id="paper-priority"><option value="normal">Normal</option><option value="high">High</option><option value="low">Low</option></select></div></div><div id="add-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" data-close>Cancel</button><button class="button primary" id="save-paper" type="submit">${icon('plus')}Add to library</button></div></form>`);attachTagSuggestions('paper-tags');$('#add-form').onsubmit=submitAdd;if($('#lookup'))$('#lookup').onclick=lookupMetadata;}
function paperInput(value){const clean=value.trim();return /^(?:link\.springer(?:nature)?\.com|dl\.acm\.org|ieeexplore\.ieee\.org|tches\.iacr\.org|eprint\.iacr\.org|ia\.cr)\//i.test(clean)?'https://'+clean:clean}
function getDoi(value){let clean=paperInput(value).replace(/^doi:\s*/i,'');try{const u=new URL(clean);if(!/^https?:$/.test(u.protocol)||u.username||u.password||u.port)return '';if(/^(?:dx\.)?doi\.org$/i.test(u.hostname))clean=decodeURIComponent(u.pathname.slice(1));else if(['link.springer.com','link.springernature.com'].includes(u.hostname)&&u.pathname.startsWith('/chapter/'))clean=decodeURIComponent(u.pathname.slice('/chapter/'.length));else if(u.hostname==='dl.acm.org'){const match=u.pathname.match(/^\/doi\/(?:abs\/|full\/|pdf\/|epdf\/)?(10\.\d{4,9}\/.+?)\/?$/i);if(!match)return '';clean=decodeURIComponent(match[1])}else return ''}catch{if(/^https?:/i.test(clean))return ''}return /^10\.\d{4,9}\/\S+$/i.test(clean)?clean:''}
function getTchesArticleId(value){try{const u=new URL(paperInput(value));if(!/^https?:$/.test(u.protocol)||u.hostname!=='tches.iacr.org'||u.username||u.password||u.port)return '';return u.pathname.match(/^\/index\.php\/TCHES\/article\/(?:view|download)\/([1-9]\d{0,9})(?:\/[1-9]\d{0,9})?\/?$/i)?.[1]||''}catch{return ''}}
function getEprintId(value){try{const u=new URL(paperInput(value));if(!/^https?:$/.test(u.protocol)||!['eprint.iacr.org','ia.cr'].includes(u.hostname)||u.username||u.password||u.port)return '';return u.pathname.match(/^\/((?:19|20)\d{2}\/[1-9]\d{0,9})(?:\.pdf)?\/?$/)?.[1]||''}catch{return ''}}
function getIeeeId(value){try{const u=new URL(paperInput(value));if(!/^https?:$/.test(u.protocol)||u.hostname!=='ieeexplore.ieee.org'||u.username||u.password||u.port)return '';const id=u.pathname.match(/^\/(?:abstract\/)?document\/([1-9]\d{0,9})\/?$/)?.[1];if(id)return id;if(['/stamp/stamp.jsp','/xpl/documentDetails.jsp','/xpls/abs_all.jsp'].includes(u.pathname)&&u.searchParams.getAll('arnumber').length===1){const article=u.searchParams.get('arnumber');return /^[1-9]\d{0,9}$/.test(article)?article:''}return ''}catch{return ''}}
async function lookupPaper(value){const doi=getDoi(value);if(doi)return crossrefPaper((await fetchJson('https://api.crossref.org/works/'+encodeURIComponent(doi))).message);const ieeeId=getIeeeId(value);if(ieeeId){const p=await fetchJson('/api/ieee?id='+encodeURIComponent(ieeeId));if(p.doi){try{return {...crossrefPaper((await fetchJson('https://api.crossref.org/works/'+encodeURIComponent(p.doi))).message),url:p.url}}catch{}}return {...p,venue:crossrefVenue({'container-title':[p.venue]})}}const id=getTchesArticleId(value);if(id)return fetchJson('/api/tches?id='+encodeURIComponent(id));const eprintId=getEprintId(value);if(eprintId)return fetchJson('/api/eprint?id='+encodeURIComponent(eprintId));throw new Error('Use an IACR ePrint link, a DOI, an IEEE Xplore or ACM Digital Library link, a Springer chapter link, or a TCHES article link. Other links can be saved with your own details.')}
async function fetchJson(url,options={}){const r=await fetch(url,{...options,signal:AbortSignal.timeout(20000)});if(!r.ok){const data=await r.json().catch(()=>({}));throw new Error(typeof data.error==='string'?data.error:`Service returned ${r.status}. Please try again.`)}return r.json()}
function crossrefVenue(w){const venue=w['container-title']?.[0]||w.event?.name||'';if(/\bACM\b/i.test(venue)&&/Conference on Computer and Communications Security/i.test(venue))return 'ACM CCS';if(/^IEEE Transactions on Information Forensics (?:and|&) Security$/i.test(venue.trim()))return 'IEEE TIFS';return venue}
function crossrefPaper(w){return {id:crypto.randomUUID(),title:w.title?.[0]||'Untitled paper',authors:(w.author||[]).map(a=>[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean).join('; '),year:(w.published?.['date-parts']||w.issued?.['date-parts'])?.[0]?.[0]||'',venue:crossrefVenue(w),doi:w.DOI||'',url:w.URL||'',tags:[],status:'unread',importance:'normal',notes:'',added:Date.now(),updated:Date.now(),metadataSource:'Crossref',type:w.type}}
async function lookupMetadata(){const source=paperInput($('#paper-url').value);const sequence=++metadataLookupSequence;lookedUpMetadata=null;const b=$('#lookup');b.disabled=true;b.textContent='Looking up\u2026';try{const p=await lookupPaper(source);if(sequence!==metadataLookupSequence||source!==paperInput($('#paper-url')?.value||'')||addMode!=='url')return;$('#paper-title').value=p.title;$('#paper-authors').value=p.authors;$('#paper-year').value=p.year;$('#paper-venue').value=p.venue;lookedUpMetadata={...p,source};$('#add-error').textContent='';toast('Citation details found. Review before saving.')}catch(e){if(sequence===metadataLookupSequence)$('#add-error').textContent=e.message+' You can still enter details manually.'}finally{b.disabled=false;b.innerHTML=icon('search')+'Look up metadata'}}
async function submitAdd(e){e.preventDefault();if(saving)return;const error=$('#add-error');const b=$('#save-paper');b.disabled=true;try{const source=paperInput($('#paper-url')?.value||'');const metadata=lookedUpMetadata?.source===source?lookedUpMetadata:null;const doi=getDoi(source)||metadata?.doi||'';if($('#lookup')?.disabled)throw new Error('Wait for the citation lookup to finish.');if(source&&!doi&&!safeUrl(source))throw new Error('Enter a valid http or https paper URL.');const ieeeId=getIeeeId(source);if(ieeeId&&papers.some(p=>getIeeeId(p.url||'')===ieeeId))throw new Error('This IEEE Xplore paper is already in your library.');const eprintId=getEprintId(source);if(eprintId&&papers.some(p=>getEprintId(p.url||'')===eprintId))throw new Error('This ePrint paper is already in your library.');if(doi&&papers.some(p=>p.doi?.toLowerCase()===doi.toLowerCase()))throw new Error('This DOI is already in your library.');const p={id:crypto.randomUUID(),title:$('#paper-title').value.trim(),authors:$('#paper-authors').value.trim(),year:Number($('#paper-year').value)||'',venue:$('#paper-venue').value.trim(),tags:parseTags($('#paper-tags').value),status:$('#paper-status').value,importance:$('#paper-priority').value,url:safeUrl(source)||(doi?'https://doi.org/'+doi:''),doi,metadataSource:metadata?.metadataSource||'',type:metadata?.type||'',notes:'',added:Date.now(),updated:Date.now()};if(!p.title)throw new Error('Enter a paper title.');papers.unshift(enrichVenue(p));await save();close();render();toast('Paper added. A new idea, collected.')}catch(err){error.textContent=err.message}finally{b.disabled=false}}
function details(id,external=false){const p=(external?recommendations:papers).find(p=>p.id===id);if(!p)return;modal(modalTitle(p.title)+`<p style="font-size:12px">${esc(p.authors)} · ${esc(p.year||'Year not recorded')}</p><div class="detail-links">${safeUrl(p.url|| (p.doi?'https://doi.org/'+p.doi:''))?`<a class="button" href="${esc(safeUrl(p.url||'https://doi.org/'+p.doi))}" target="_blank" rel="noopener noreferrer">${icon('link')}Open paper ↗</a>`:''}${!external?`<button class="button" data-cite="${esc(p.id)}">${icon('download')}Cite</button>}`:''}</div>${external?`<p>Found via Crossref. Check the publisher page for the full text and publication details.</p><div class="modal-actions"><button class="button primary" data-import="${esc(p.id)}">Add to library</button></div>`:`<form id="detail-form"><div class="two-fields"><div class="field"><label for="detail-status">Reading status</label><select id="detail-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div><div class="field"><label for="detail-priority">Importance</label><select id="detail-priority"><option value="high">High</option><option value="normal">Normal</option><option value="low">Low</option></select></div></div><div class="field"><label for="detail-title">Title</label><input id="detail-title" value="${esc(p.title)}" required></div><div class="field"><label for="detail-authors">Authors</label><input id="detail-authors" value="${esc(p.authors)}"></div><div class="two-fields"><div class="field"><label for="detail-year">Publication year</label><input id="detail-year" type="number" min="1400" max="2100" value="${esc(p.year)}"></div><div class="field"><label for="detail-venue">Conference / journal</label><input id="detail-venue" value="${esc(p.venue)}"></div></div><div class="field"><label for="detail-url">Paper source link</label><input id="detail-url" type="url" value="${esc(p.url||'')}" placeholder="https://…"></div>${tagField('detail-tags',p.tags.join(', '))}<div class="field"><label for="detail-notes">Reading notes</label><textarea id="detail-notes" placeholder="Key ideas, questions, and things to come back to…">${esc(p.notes)}</textarea></div><details><summary style="font-size:12px;cursor:pointer">Venue rank & impact factor</summary><p style="font-size:11px">Record a metric from a source such as CORE or Journal Citation Reports. These are venue metrics; they are not a score for this paper.</p><div class="two-fields"><div class="field"><label for="metric-type">Metric</label><select id="metric-type"><option>CORE rank</option><option>Journal impact factor</option><option>SJR quartile</option></select></div><div class="field"><label for="metric-value">Value</label><input id="metric-value" value="${esc(p.rank||'')}" placeholder="e.g. A* or 4.2"></div></div><div class="two-fields"><div class="field"><label for="metric-year">Metric year</label><input id="metric-year" type="number" min="2000" max="2100" value="${esc(p.metricYear||'')}" placeholder="2025"></div><div class="field"><label for="metric-source">Source URL</label><input id="metric-source" type="url" value="${esc(p.metricSource||'')}" placeholder="https://…"></div></div>${safeUrl(p.metricSource)?`<a href="${esc(p.metricSource)}" target="_blank" rel="noopener noreferrer" style="font-size:11px">View recorded source ↗</a>`:''}</details><div id="detail-error" class="error"></div><div class="modal-actions"><button type="button" class="button danger" data-delete="${esc(p.id)}">Remove paper</button><button class="button primary" type="submit">Save changes</button></div></form>`}`);if(!external){attachTagSuggestions('detail-tags');$('#detail-status').value=p.status;$('#detail-priority').value=p.importance;$('#metric-type').value=p.metricType||'CORE rank';$('#detail-form').onsubmit=async e=>{try{e.preventDefault();if(saving)return;const rank=$('#metric-value').value.trim();if(rank&&(!$('#metric-year').value||!safeUrl($('#metric-source').value))){$('#detail-error').textContent='Add a year and a valid source URL for the venue metric.';return}Object.assign(p,{title:$('#detail-title').value.trim(),authors:$('#detail-authors').value.trim(),year:Number($('#detail-year').value)||'',venue:$('#detail-venue').value.trim(),status:$('#detail-status').value,importance:$('#detail-priority').value,tags:parseTags($('#detail-tags').value),notes:$('#detail-notes').value,url:safeUrl($('#detail-url').value.trim()),rank,metricType:$('#metric-type').value,metricYear:$('#metric-year').value,metricSource:$('#metric-source').value,updated:Date.now()});await save();close();render();toast('Paper updated.')}catch(err){if(confirmed&&papers.some(a=>a.id===id)){details(id);$('#detail-error').textContent=err.message}else toast(err.message)}};}}
function bibEscape(s){return String(s||'').replace(/[\\{}%&#_$]/g,c=>'\\'+c)}
function citation(p,format){const isPreprint=p.type==='posted-content'||(!p.type&&/Cryptology ePrint Archive/i.test(p.venue||''));const isConference=!isPreprint&&/proceedings|conference|symposium|EUROCRYPT/i.test(p.type||p.venue);const authors=p.authors.split(';').map(a=>a.trim()).filter(Boolean);if(format==='plain')return `${authors.join(', ')}${p.year?' ('+p.year+').':'.'} ${p.title}. ${p.venue||''}.${p.doi?' https://doi.org/'+p.doi:p.url?' '+p.url:''}`;if(format==='ris')return `TY  - ${isConference?'CPAPER':'JOUR'}\nTI  - ${p.title}\n${authors.map(a=>'AU  - '+a).join('\n')}\nPY  - ${p.year}\nJO  - ${p.venue}\nDO  - ${p.doi||''}\nUR  - ${p.url||''}\nER  -`;const name=authors[0]?.split(' ').at(-1)?.replace(/[^a-zA-Z]/g,'')||'paper';return `@${isPreprint?'misc':isConference?'inproceedings':'article'}{${name}${p.year||''}_${p.id.slice(-4)},\n  title = {${bibEscape(p.title)}},\n  author = {${authors.map(bibEscape).join(' and ')}},\n  year = {${p.year}},\n  ${isPreprint?'howpublished':isConference?'booktitle':'journal'} = {${bibEscape(p.venue)}}${p.doi?',\n  doi = {'+bibEscape(p.doi)+'}':''}${p.url?',\n  url = {'+bibEscape(p.url)+'}':''}\n}`}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function cite(id){const list=id?papers.filter(p=>p.id===id):papers;let format='bibtex';modal(modalTitle(id?'A citation, ready to go.':'Export your library.')+`<div class="field"><label for="cite-format">Citation format</label><select id="cite-format"><option value="bibtex">BibTeX</option><option value="ris">RIS</option><option value="plain">Plain text</option></select></div><p style="font-size:11px">${list.length} ${list.length===1?'paper':'papers'} · Review metadata for your preferred citation style.</p><pre class="citation-block" id="citation-output"></pre><div class="modal-actions"><button class="button" id="copy-citation">Copy citations</button><button class="button primary" id="download-citation">${icon('download')}Download</button></div>`);const content=()=>list.map(p=>citation(p,format)).join('\n\n');$('#citation-output').textContent=content();$('#cite-format').onchange=e=>{format=e.target.value;$('#citation-output').textContent=content()};$('#copy-citation').onclick=async()=>{try{await navigator.clipboard.writeText(content());toast('Citations copied.')}catch{toast('Clipboard unavailable. Use Download instead.')}};$('#download-citation').onclick=()=>download('folio-citations.'+({bibtex:'bib',ris:'ris',plain:'txt'}[format]),content())}
function pickPaper(){const list=filtered().filter(p=>p.status==='unread');if(!list.length){if(papers.some(p=>p.status==='unread'))toast('No unread papers match your current filters.');else navigate('discover');return}let candidates=list;if($('#prefer-important')?.checked!==false){const high=list.filter(p=>p.importance==='high');if(high.length)candidates=high}const chosen=$('#random-pick')?.checked?candidates[Math.floor(Math.random()*candidates.length)]:[...candidates].sort((a,b)=>a.added-b.added)[0];details(chosen.id);toast('Picked from your unread papers.')}
function renderDiscover(){const tags=[...new Set(papers.flatMap(p=>p.tags))].slice(0,4);$('#main').innerHTML=heading('Follow your curiosity.','Find papers beyond your library, guided by what interests you.',false)+`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('compass')} OPEN A NEW CHAPTER</div><h2>There’s always another idea to explore.</h2><p>Search live scholarly metadata, or use your library’s topics as a starting point.</p><button class="button" id="recommend">${icon('spark')}Recommend from my interests ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="book-cover"></div><div class="book-front"><small>NEW PERSPECTIVES</small><em>Stay<br>curious.</em><div class="lines"></div></div><span class="spark">✦</span></div></section><form class="discover-search" id="discover-form"><label class="search">${icon('search')}<input id="discover-query" placeholder="Explore a topic, title, or author…" aria-label="Search scholarly papers" required></label><button class="button primary" id="discover-submit">Find papers</button></form><div class="tags">${tags.map(t=>`<button class="button" data-discover-topic="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="section-title"><h2>Beyond your library</h2><span class="subtle-link">Live metadata by Crossref</span></div><div id="discover-message" class="discover-message">${esc(discoverState||'Choose a topic to discover papers. Recommendations appear only when you ask.')}</div><div id="discover-results" class="paper-grid">${recommendations.map(p=>card(p,true)).join('')}</div>`;$('#discover-form').onsubmit=e=>{e.preventDefault();searchDiscovery($('#discover-query').value)};$('#recommend').onclick=()=>{const interests=papers.filter(p=>p.importance==='high').flatMap(p=>p.tags);const topic=[...new Set(interests)].slice(0,2).join(' ')||tags.slice(0,2).join(' ');if(!topic){toast('Add tags to your papers, or search a topic.');return}$('#discover-query').value=topic;searchDiscovery(topic)};}
let searchSequence=0;
async function searchDiscovery(topic){const seq=++searchSequence;const b=$('#discover-submit');b.disabled=true;$('#discover-message').textContent='Looking for new perspectives…';try{const data=await fetchJson('https://api.crossref.org/works?query.bibliographic='+encodeURIComponent(topic)+'&rows=40');if(seq!==searchSequence||view!=='discover')return;const existing=new Set(papers.map(p=>(p.doi||'').toLowerCase()));const titles=new Set(papers.map(p=>p.title.toLowerCase()));const seen=new Set();recommendations=data.message.items.filter(w=>['journal-article','proceedings-article','posted-content','dissertation'].includes(w.type)).map(crossrefPaper).filter(p=>!existing.has(p.doi.toLowerCase())&&!titles.has(p.title.toLowerCase())).filter(p=>{const t=p.title.toLowerCase();if(seen.has(t))return false;seen.add(t);return true}).slice(0,12).map(p=>({...p,tags:[topic.length>35?'Related research':topic]}));discoverState=`${recommendations.length} papers related to “${topic}” · Papers already in your library are excluded.`;$('#discover-message').textContent=discoverState;$('#discover-results').innerHTML=recommendations.length?recommendations.map(p=>card(p,true)).join(''):'<div class="empty">No new papers found. Try a broader topic.</div>'}catch(e){if(view==='discover'&&seq===searchSequence){$('#discover-message').textContent=e.message+' Your existing results are still shown.'}}finally{b.disabled=false}}
async function importPaper(id){const p=recommendations.find(p=>p.id===id);if(!p)return;if(papers.some(a=>a.doi&&a.doi===p.doi)){toast('Already in your library.');return}papers.unshift(enrichVenue({...p,added:Date.now(),updated:Date.now()}));recommendations=recommendations.filter(a=>a.id!==id);await save();close();render();toast('A new perspective added to your library.')}
function renderSettings(){if(remoteMode){renderRemoteSettings();return}$('#main').innerHTML=heading('Your library, your way.','Manage collections, citations, and library backups.',false)+`${collectionSettings()}<section class="panel"><h2>Local backup & recovery</h2><p>Your citations, links, tags, and notes are saved in this browser. Export a JSON backup before clearing browser data.</p><div class="setting-row"><button id="json-export" class="button">${icon('download')}Export library JSON</button><button id="json-import" class="button">Import library JSON</button><input type="file" id="json-file" accept="application/json,.json" hidden><button id="settings-cite" class="button">Export citations</button></div></section>${papers.some(p=>p.sample)?'<section class="panel danger-zone"><div><h2>Make it your own</h2><p>Remove sample papers to start with your own research.</p></div><button class="button danger" id="remove-samples">Remove samples</button></section>':''}`;$('#json-export').onclick=()=>download('folio-library.json',JSON.stringify({version:1,papers,exported:new Date().toISOString()},null,2),'application/json');$('#json-import').onclick=()=>$('#json-file').click();$('#settings-cite').onclick=()=>cite();$('#json-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Library JSON must be smaller than 10 MB.');mergeBackup(JSON.parse(await file.text()));await save();render();toast('Library backup merged.')}catch(err){toast('Import failed: '+err.message)}};}
function validateBackup(data){if(data?.version!==1||!Array.isArray(data.papers)||data.papers.length>10000)throw new Error('Not a supported Folio library backup.');return data.papers.map(p=>{if(typeof p.id!=='string'||p.id.length>100||!p.id||typeof p.title!=='string'||!p.title.trim())throw new Error('Invalid paper record.');return {id:p.id,title:p.title.slice(0,500),authors:String(p.authors||'').slice(0,5000),year:Number(p.year)||'',venue:String(p.venue||'').slice(0,1000),tags:Array.isArray(p.tags)?p.tags.filter(t=>typeof t==='string').slice(0,50):[],status:['read','unread','reading'].includes(p.status)?p.status:'unread',importance:['high','normal','low'].includes(p.importance)?p.importance:'normal',url:safeUrl(p.url),doi:getDoi(String(p.doi||'')),notes:String(p.notes||'').slice(0,100000),added:Number(p.added)||Date.now(),updated:Number(p.updated)||Number(p.added)||Date.now(),sample:p.sample===true,rank:String(p.rank||''),metricType:String(p.metricType||''),metricYear:String(p.metricYear||''),metricSource:safeUrl(p.metricSource),type:String(p.type||'')}})}
function mergeBackup(data){const incoming=validateBackup(data);const map=new Map(papers.map(p=>[p.id,citationOnly(p)]));for(const p of incoming){const current=map.get(p.id);if(!current||p.updated>current.updated)map.set(p.id,p)}papers=[...map.values()]}
function confirmAction(title,message,action){modal(modalTitle(title)+`<p>${esc(message)}</p><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="confirm-action">Confirm</button></div>`);$('#confirm-action').onclick=async()=>{try{if(saving)return;await action();close();render()}catch(e){toast(e.message)}}}
document.addEventListener('click',async e=>{try{if(saving)return;const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-manage-collections'))manageCollections();if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.collection)navigate('library',b.dataset.collection);if(b.hasAttribute('data-filter-tag')){collection=collection===b.dataset.filterTag?'':b.dataset.filterTag;if(view==='library')location.hash=collection?'collection='+encodeURIComponent(collection):'library';render();}if(b.hasAttribute('data-close'))close();if(b.dataset.paper)details(b.dataset.paper);if(b.dataset.external)details(b.dataset.external,true);if(b.dataset.star){const p=papers.find(p=>p.id===b.dataset.star);p.importance=p.importance==='high'?'normal':'high';p.updated=Date.now();await save();render();}if(b.dataset.import)await importPaper(b.dataset.import);if(b.dataset.cite)cite(b.dataset.cite);if(b.dataset.delete)confirmAction('Remove this paper?','This removes the citation, link, and notes from your library.',async()=>{const p=papers.find(p=>p.id===b.dataset.delete);papers=papers.filter(item=>item.id!==p.id);await save();toast('Paper removed.')});if(b.dataset.addTab){addMode=b.dataset.addTab;renderAdd()}if(b.dataset.layout){layout=b.dataset.layout;render()}if(b.dataset.discoverTopic){$('#discover-query').value=b.dataset.discoverTopic;searchDiscovery(b.dataset.discoverTopic)}if(['add-paper','empty-add'].includes(b.id))addPaper();if(['top-export','export-library'].includes(b.id))cite();if(b.id==='pick-paper')pickPaper();if(b.id==='remove-samples')confirmAction('Start with your own papers?','Remove the sample papers. Papers you added yourself will stay in your library.',async()=>{papers=papers.filter(p=>!p.sample);await save();toast('Sample papers removed.')});if(b.id==='add-collection'){modal(modalTitle('A new collection.')+'<form id="collection-form"><div class="field"><label for="collection-name">Collection name</label><input id="collection-name" required maxlength="60" placeholder="e.g. Post-quantum cryptography"></div><div class="modal-actions"><button class="button primary">Create collection</button></div></form>');$('#collection-form').onsubmit=async e=>{try{e.preventDefault();if(saving)return;const t=$('#collection-name').value.trim();if(!t)return;settings.collections=[...new Set([...(settings.collections||[]),t])];await saveSettings();close();navigate('library',t);toast('Collection created. Add its tag to any paper.')}catch(err){toast(err.message)}}}}catch(err){toast(err.message)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
hydrate();const hash=location.hash.slice(1);if(hash.startsWith('collection=')){collection=decodeURIComponent(hash.slice(11))}else if(labels[hash])view=hash;if(remoteMode)startRemote();else render();

window.addEventListener('hashchange',()=>{if(remoteMode&&invitationToken()){showLogin();return}const h=location.hash.slice(1);const tag=h.startsWith('collection=')?decodeURIComponent(h.slice(11)):'';const next=tag?'library':(labels[h]?h:'library');if(next!==view||tag!==collection){view=next;collection=tag;query='';statusFilter='all';priorityFilter='all';render()}});


async function remoteApi(path,options={}){
 const epoch=accountEpoch;
 const r=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...(currentUser?{'X-Folio-User':String(currentUser.id)}:{}),...options.headers},signal:AbortSignal.timeout(20000)});
 const data=await r.json();
 if(epoch!==accountEpoch)throw new Error('The account changed while this request was running.');
 if(!r.ok){if(data.accountChanged||(r.status===401&&!['/api/login','/api/register','/api/password'].includes(path)))showLogin();const err=new Error(data.error||'Server request failed.');err.status=r.status;err.library=data.library;throw err}return data;
}
function acceptRemote(data){if(data.user&&currentUser?.id!==data.user.id){const sessionToken=csrf;clearAccountState();csrf=sessionToken;currentUser=data.user}papers=data.papers.map(citationOnly);settings=citationSettings(data.settings);revision=data.revision;confirmed=structuredClone(data)}
async function persistRemote(){
 if(saving)throw new Error('A save is in progress. Please wait.');
 saving=true;
 try{const data=await remoteApi('/api/library',{method:'PUT',body:JSON.stringify({papers,settings,revision})});acceptRemote(data);updateSidebar()}
 catch(err){if(err.library)acceptRemote(err.library);else if(confirmed)acceptRemote(confirmed);render();toast(err.message);throw err}
 finally{saving=false}
}
function clearAccountState(){accountEpoch++;currentUser=null;papers=[];settings={};confirmed=null;revision=0;csrf='';recommendations=[];discoverState='';searchSequence++;metadataLookupSequence++;lookedUpMetadata=null;collection='';query='';statusFilter='all';priorityFilter='all';close()}
function invitationToken(){return location.hash.match(/^#invite=([a-f0-9]{64})$/)?.[1]||''}
function showLogin(){
 clearAccountState();updateSidebar();const invitation=invitationToken();
 $('#main').innerHTML=heading(invitation?'Your research starts here.':'Your research, securely collected.',invitation?'Create your own account with this invitation.':'Sign in to your private paper library.',false)+`<section class="panel"><form id="login-form"><div class="field"><label for="login-username">Username</label><input id="login-username" autocomplete="username" required minlength="3" maxlength="40" placeholder="${invitation?'Choose a username':'owner'}"><small>3–40 letters, numbers, dots, underscores, or hyphens.</small></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" autocomplete="${invitation?'new-password':'current-password'}" required ${invitation?'minlength="16"':''} maxlength="1024">${invitation?'<small>Use at least 16 characters.</small>':''}</div>${invitation?'<div class="field"><label for="register-confirm">Confirm password</label><input id="register-confirm" type="password" autocomplete="new-password" required maxlength="1024"></div>':''}<div class="error" id="login-error" role="alert"></div><button class="button primary" id="login-submit">${invitation?'Create account':'Sign in'}</button></form>${invitation?'<button type="button" class="button" id="return-login">Already have an account? Sign in</button>':'<p>New accounts require an invitation from the owner.</p>'}</section>`;
 if(invitation)$('#return-login').onclick=()=>{location.hash='library';showLogin()};
 $('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('#login-submit');b.disabled=true;const password=$('#login-password').value;try{if(invitation&&password!==$('#register-confirm').value)throw new Error('The passwords do not match.');const data=await remoteApi(invitation?'/api/register':'/api/login',{method:'POST',body:JSON.stringify({username:$('#login-username').value,password,...(invitation?{invitation}:{})})});currentUser=data.user;csrf=data.csrf;view='library';if(invitation){window.history?.replaceState(null,'',location.pathname+location.search+'#library');location.hash='library'}await loadRemote();}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}};
}
async function loadRemote(){acceptRemote(await remoteApi('/api/library'));render()}
async function startRemote(){
 if(invitationToken()){showLogin();return}
 $('#storage-label').textContent='Saved on your server';$('.local-status').innerHTML='<i></i> Server library';
 $('#main').innerHTML=heading('Opening your library…','Connecting to your server.',false);
 try{const session=await remoteApi('/api/session');currentUser=session.user||null;csrf=session.csrf;await loadRemote()}catch(err){if(err.status!==401){$('#main').innerHTML=heading('Cannot reach your library.',esc(err.message),false)+`<button class="button" id="retry-server">Try again</button>`;$('#retry-server').onclick=startRemote}}
}
function accountSettings(){return `<section class="panel"><h2>Your account</h2><p>Signed in as <strong>${esc(currentUser?.username||'')}</strong>. Your library is private to this account.</p><form id="password-form"><div class="field"><label for="current-password">Current password</label><input id="current-password" type="password" autocomplete="current-password" required maxlength="1024"></div><div class="two-fields"><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" autocomplete="new-password" required minlength="16" maxlength="1024"></div><div class="field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" type="password" autocomplete="new-password" required maxlength="1024"></div></div><p class="error" id="password-error" role="alert"></p><button class="button" id="change-password">Change password</button></form>${currentUser?.role==='owner'?'<div class="setting-row"><button type="button" class="button" id="manage-users">Manage users & invitations</button></div>':''}</section>`}
async function manageUsers(){
 modal(modalTitle('Users & invitations.')+'<p>Loading accounts…</p>');
 try{const [users,invites]=await Promise.all([remoteApi('/api/admin/users'),remoteApi('/api/admin/invitations')]);if(currentUser?.role!=='owner')return;
 modal(modalTitle('Users & invitations.')+`<p>Each user has a private library for citations, links, tags, and notes. Invitations can be used by multiple people until they expire after seven days or you revoke them.</p><div id="account-manager">${users.users.map(user=>`<div class="collection-manager-row"><div><strong>${esc(user.username)}</strong><small>${user.role==='owner'?'Owner':user.enabled?'Active':'Disabled'}</small></div>${user.role==='owner'?'':`<button type="button" class="button" data-account-id="${user.id}" data-account-enable="${user.enabled?'false':'true'}">${user.enabled?'Disable':'Enable'}</button>`}</div>`).join('')}<h3>Active invitations</h3>${invites.invitations.length?invites.invitations.map(invite=>`<div class="collection-manager-row"><span>Expires ${esc(new Date(invite.expires).toLocaleDateString())}</span><button type="button" class="button danger" data-revoke-invite="${esc(invite.id)}">Revoke</button></div>`).join(''):'<p>No active invitations.</p>'}</div><div class="field"><label for="new-invitation">New invitation link</label><input id="new-invitation" readonly placeholder="Create an invitation to get a link"><small>Share privately. Copy the link now; it cannot be retrieved later.</small></div><p id="account-error" class="error" role="alert"></p><div class="modal-actions"><button type="button" class="button" data-close>Done</button><button type="button" class="button" id="copy-invitation">Copy link</button><button type="button" class="button primary" id="create-invitation">Create invitation</button></div>`);
 $('#create-invitation').onclick=async()=>{const b=$('#create-invitation');b.disabled=true;try{const invite=await remoteApi('/api/admin/invitations',{method:'POST',body:'{}'});$('#new-invitation').value=invite.url;toast('Invitation created. Copy the link before closing.')}catch(err){$('#account-error').textContent=err.message}finally{b.disabled=false}};
 $('#copy-invitation').onclick=async()=>{try{const link=$('#new-invitation').value;if(!link)throw new Error('Create an invitation first.');await navigator.clipboard.writeText(link);toast('Invitation link copied.')}catch(err){$('#account-error').textContent=err.message||'Copy the link manually.'}};
 $('#account-manager').onclick=async e=>{const b=e.target.closest('button');if(!b)return;b.disabled=true;try{if(b.dataset.revokeInvite)await remoteApi('/api/admin/invitations/'+b.dataset.revokeInvite,{method:'DELETE',body:'{}'});if(b.dataset.accountId)await remoteApi('/api/admin/users/'+b.dataset.accountId,{method:'PATCH',body:JSON.stringify({enabled:b.dataset.accountEnable==='true'})});await manageUsers()}catch(err){$('#account-error').textContent=err.message}finally{b.disabled=false}};
 }catch(err){if(currentUser?.role==='owner')modal(modalTitle('Users & invitations.')+`<p class="error">${esc(err.message)}</p>`)}
}
function renderRemoteSettings(){
 $('#main').innerHTML=heading('Your library, wherever you read.','Your citations, links, and reading notes in one place.',false)+`${accountSettings()}${collectionSettings()}<section class="panel"><h2>Server library & recovery</h2><p>Your private library loads on every signed-in device. Refresh to see edits made elsewhere. Conflicting saves load your latest library for review. JSON exports contain citation details, links, tags, and notes.</p><div class="setting-row"><button class="button" id="refresh-library">Reload from server</button><button class="button" id="json-export">Export library JSON</button><button class="button" id="json-import">Import library JSON</button><button class="button" id="logout">Sign out</button><input type="file" id="json-file" accept="application/json,.json" hidden></div><p>To migrate a browser library, export its JSON and import it here.</p></section>`;
 $('#password-form').onsubmit=async e=>{e.preventDefault();const b=$('#change-password');b.disabled=true;try{if($('#new-password').value!==$('#confirm-password').value)throw new Error('The passwords do not match.');const result=await remoteApi('/api/password',{method:'POST',body:JSON.stringify({currentPassword:$('#current-password').value,password:$('#new-password').value})});csrf=result.csrf;$('#current-password').value='';$('#new-password').value='';$('#confirm-password').value='';$('#password-error').textContent='';toast('Password changed. Other sessions were signed out.')}catch(err){$('#password-error').textContent=err.message}finally{b.disabled=false}};
 if(currentUser?.role==='owner')$('#manage-users').onclick=manageUsers;
 $('#refresh-library').onclick=async()=>{try{if(saving)return;await loadRemote();toast('Latest server library loaded.')}catch(err){toast(err.message)}};
 $('#json-export').onclick=()=>download('folio-library.json',JSON.stringify({version:1,papers,exported:new Date().toISOString()},null,2),'application/json');
 $('#json-import').onclick=()=>$('#json-file').click();
 $('#json-file').onchange=async e=>{try{if(saving)return;const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Library JSON must be smaller than 10 MB.');mergeBackup(JSON.parse(await file.text()));await save();render();toast('Library imported to server.')}catch(err){toast(err.message)}};
 $('#logout').onclick=async()=>{try{if(saving)return;await remoteApi('/api/logout',{method:'POST',body:'{}'});showLogin()}catch(err){toast(err.message)}};
}

function renderPhoneLibrary(){
 const unread=papers.filter(p=>p.status==='unread').length;
 const read=papers.filter(p=>p.status==='read').length;
 const tags=[...new Set([...papers.flatMap(p=>p.tags||[]),...(settings.collections||[])])];
 const title=collection||(view==='queue'?'Your next read.':view==='favorites'?'Worth keeping close.':'Your reading shelf.');
 $('#main').innerHTML=`<div class="phone-heading"><div><div class="eyebrow">A LITTLE SPACE FOR BIG IDEAS</div><h1>${esc(title)}</h1><p>${view==='queue'?'One paper. A new perspective.':view==='favorites'?'The ideas you want to come back to.':`${papers.length} collected · ${read} read`}</p></div><button class="phone-add" id="add-paper" aria-label="Add paper">${icon('plus')}</button></div>
 <section class="phone-next"><div class="phone-next-top"><span>${icon('book')} ${unread} waiting to be read</span><span aria-hidden="true">✦</span></div><h2>${unread?'Make time for one good idea.':'Ready for something new?'}</h2><button class="button primary" id="pick-paper">${unread?'Pick my next read':'Discover papers'}${icon('arrow')}</button>${view==='queue'?'<div class="queue-options"><label><input id="prefer-important" type="checkbox" checked> Important first</label><label><input id="random-pick" type="checkbox"> Random pick</label></div>':''}</section>
 <div class="phone-section"><h2>${collection?'In this collection':view==='queue'?'Unread papers':view==='favorites'?'Important papers':'Your papers'} <span id="result-count" aria-live="polite"></span></h2></div>
 <label class="search phone-search">${icon('search')}<input id="search" type="search" placeholder="Search your papers…" aria-label="Search papers" value="${esc(query)}"></label>
 <div class="phone-collections" aria-label="Collections"><button data-view="library" class="${!collection&&view==='library'?'selected':''}">All papers</button>${tags.map(t=>`<button data-collection="${esc(t)}" class="${collection===t?'selected':''}">${esc(t)}</button>`).join('')}<button type="button" data-manage-collections>Manage</button><button id="add-collection" class="phone-new-collection" aria-label="Add collection">${icon('plus')}</button></div>
 <details class="phone-filters" ${statusFilter!=='all'||priorityFilter!=='all'||sort!=='newest'?'open':''}><summary>${icon('list')}Filter & sort</summary><div class="phone-filter-fields"><label>Reading status<select id="status-filter"><option value="all">All statuses</option><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></label><label>Importance<select id="priority-filter"><option value="all">All importance</option><option value="high">High</option><option value="normal">Normal</option><option value="low">Low</option></select></label><label>Sort by<select id="sort"><option value="newest">Newest added</option><option value="oldest">Oldest added</option><option value="year">Publication year</option><option value="title">Title A–Z</option><option value="importance">Importance</option></select></label></div></details>
 <div class="paper-grid phone-papers" id="paper-results"></div>${papers.some(p=>p.sample)?'<div class="sample-note"><span>Sample library</span><button id="remove-samples">Remove samples</button></div>':''}`;
 renderPapers();
 $('#status-filter').value=statusFilter;$('#priority-filter').value=priorityFilter;$('#sort').value=sort;
 $('#search').oninput=e=>{query=e.target.value;renderPapers()};
 $('#status-filter').onchange=e=>{statusFilter=e.target.value;renderPapers()};
 $('#priority-filter').onchange=e=>{priorityFilter=e.target.value;renderPapers()};
 $('#sort').onchange=e=>{sort=e.target.value;renderPapers()};
}
phoneMedia?.addEventListener('change',()=>render());


function desktopTagFilters(){
 const tags=[...new Set([...papers.flatMap(p=>p.tags||[]),...(settings.collections||[])])].sort((a,b)=>a.localeCompare(b));
 const chip=(tag,label,count)=>`<button class="filter-tag ${collection===tag?'selected':''}" data-filter-tag="${esc(tag)}" aria-pressed="${collection===tag}"><span>${esc(label)}</span><span class="filter-tag-count">${count}</span></button>`;
 return `<section class="desktop-collections" aria-labelledby="tag-filter-heading"><div class="tag-filter-heading"><h3 id="tag-filter-heading">Collections & tags</h3><button type="button" class="button" data-manage-collections>Manage collections</button><span>${collection?`Filtering by ${esc(collection)}`:'Choose a tag to filter your papers'}</span></div><div class="filter-tag-list">${chip('','All collections',papers.length)}${tags.map(tag=>chip(tag,tag,papers.filter(p=>(p.tags||[]).includes(tag)).length)).join('')}</div>${tags.length?'':'<p class="tag-filter-empty">Add tags to a paper to organize your collections.</p>'}</section>`;
}
